<?php
declare(strict_types=1);
namespace ServiceYar\Settings;
use ServiceYar\Auth\Authorization; use ServiceYar\Database\Connection;
final class SettingsService {
 private static function scope(int $uid,int $aid): void { Authorization::requireAgencyAccess($uid,$aid); }
 public static function get(int $uid,int $aid): array { Authorization::requirePermission($uid,'settings.view'); self::scope($uid,$aid); $s=Connection::get()->prepare('SELECT setting_key,setting_value,is_secret FROM agency_settings WHERE agency_id=:a ORDER BY setting_key'); $s->execute(['a'=>$aid]); $out=[]; foreach($s as $r){ if(!(bool)$r['is_secret']&&$r['setting_key']!=='neshan_service_key')$out[$r['setting_key']]=$r['setting_value']; } return $out; }
 public static function put(int $uid,int $aid,array $settings): array { Authorization::requirePermission($uid,'settings.manage'); self::scope($uid,$aid); $pdo=Connection::get(); $owns=!$pdo->inTransaction();$savepoint='settings_'.bin2hex(random_bytes(4));if($owns)$pdo->beginTransaction();else $pdo->exec('SAVEPOINT '.$savepoint); try{ $q=$pdo->prepare('INSERT INTO agency_settings(agency_id,setting_key,setting_value,is_secret) VALUES(:a,:k,:v,:secret) ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value),is_secret=VALUES(is_secret)'); foreach($settings as $k=>$v){ if($k==='company_location'){if(is_string($v))$v=json_decode($v,true);if(!is_array($v))throw new \ServiceYar\Auth\AuthException(422,'موقعیت شرکت نامعتبر است.','VALIDATION_ERROR');$v=\ServiceYar\Integrations\Neshan::coordinate($v['latitude']??null,$v['longitude']??null);} if($k==='neshan_service_key'){if($v==='')continue;if(!is_string($v)||!preg_match('/^service\.[a-zA-Z0-9-]{16,200}$/D',$v))throw new \ServiceYar\Auth\AuthException(422,'کلید سرویس نشان نامعتبر است.','VALIDATION_ERROR');} if($k==='neshan_web_key'&&(!is_string($v)||($v!==''&&!preg_match('/^web\.[a-zA-Z0-9-]{16,200}$/D',$v))))throw new \ServiceYar\Auth\AuthException(422,'کلید وب نشان نامعتبر است.','VALIDATION_ERROR');if($k==='map_provider'&&!in_array($v,['neshan','osm'],true))throw new \ServiceYar\Auth\AuthException(422,'نقشه نامعتبر است.','VALIDATION_ERROR'); if($k===\ServiceYar\Domain\FinancialAccounts::KEY)$v=\ServiceYar\Domain\FinancialAccounts::validate($uid,$aid,$v); if($k===\ServiceYar\Domain\AgencyPaymentMethods::KEY)$v=\ServiceYar\Domain\AgencyPaymentMethods::validate($v); if($k===\ServiceYar\Domain\FinancialRules::KEY)$v=\ServiceYar\Domain\FinancialRules::validate($v); if($k===\ServiceYar\Domain\DriverDeductionPolicy::KEY)$v=\ServiceYar\Domain\DriverDeductionPolicy::validate($v); if(!preg_match('/^[a-z][a-z0-9_.-]{1,149}$/i',(string)$k))throw new \ServiceYar\Auth\AuthException(422,'کلید تنظیمات نامعتبر است.','VALIDATION_ERROR'); if(is_array($v)||is_object($v))$v=json_encode($v,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES); $q->execute(['a'=>$aid,'k'=>$k,'v'=>$v===null?null:(string)$v,'secret'=>$k==='neshan_service_key'?1:0]); } if($owns)$pdo->commit();else $pdo->exec('RELEASE SAVEPOINT '.$savepoint); return self::get($uid,$aid); }catch(\Throwable $e){if($owns){if($pdo->inTransaction())$pdo->rollBack();}else $pdo->exec('ROLLBACK TO SAVEPOINT '.$savepoint);throw $e;} }
}
